//! Diagnostic labels and caller-supplied validation results. AuthorityEffect: None.
//!
//! Unit names identify obligations; this file does not execute their checkers.
//! Reports preserve supplied flags and diagnostics, including empty reports.
//! Public fields are metadata, not an authenticated mathematical certificate.

// ---------------------------------------------------------------------------
// Validation unit identifiers (spec §4)
// ---------------------------------------------------------------------------

/// Identifiers for all functor validation units.
///
/// These name validation obligations and serve as diagnostic keys.
/// Constructing a label does not establish the named obligation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum FunctorValidation {
    Name,
    MappingDomain,
    // Covariant functor (spec §4)
    ObjectTotality,
    MorphismTotality,
    BoundaryPreservation,
    IdentityPreservation,
    CompositionPreservation,

    // Contravariant functor (spec §4)
    ContravariantIdentityPreservation,
    ContravariantCompositionReversal,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum NatTransValidation {
    Name,
    FunctorBinding,
    ComponentDomain,
    ComponentBoundary,
    NaturalitySquare,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum AdjunctionValidation {
    UnitNaturality,
    CounitNaturality,
    TriangleLeft,
    TriangleRight,
    HomSetMembership,
    HomBijectionTotality,
    HomBijectionRoundTrip,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ProfunctorValidation {
    DimapIdentity,
    DimapComposition,
    StrongFirstSecond,
    ClosedInteraction,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum HigherFunctorValidation {
    TwoFunctorObjectMap,
    TwoFunctorOneMorphismMap,
    TwoFunctorTwoMorphismMap,
    TwoFunctorCompositionPreservation,
    TwoFunctorIdentityPreservation,
    PseudofunctorPentagonCoherence,
    PseudofunctorTriangleCoherence,
    InterchangeLaw,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum CoendValidation {
    /// Quotient respects all morphisms (spec §14).
    Dinaturality,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum KanExtensionValidation {
    /// Lan is universal (spec §16).
    UniversalProperty,
    /// Lan_id F ≅ F (Yoneda unit law, spec §16).
    YonedaUnitLaw,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum CauchyValidation {
    /// r ∘ s = id_R, s ∘ r = e (spec §17).
    IdempotentSplitting,
    /// All idempotents split (spec §17).
    CauchyCompleteness,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum MonadValidation {
    /// μ ∘ Tη = id_T (spec §22).
    UnitLeft,
    /// μ ∘ ηT = id_T (spec §22).
    UnitRight,
    /// μ ∘ Tμ = μ ∘ μT (spec §22).
    Associativity,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum CondensationValidation {
    /// Base splitting laws: r∘s = id, s∘r = e (spec §21).
    BaseSplitting,
    /// Homotopy coherence at each level (spec §21).
    CoherenceWitness,
    /// All condensations split (∞-Cauchy, spec §21).
    InfinityCauchyCompleteness,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum LawvereValidation {
    /// Theory respects finite products (spec §25).
    ProductPreservation,
    /// Composition = substitution (spec §25).
    SubstitutionAssociativity,
    /// All idempotent operations split (spec §25).
    CauchyCompleteness,
    /// Theory ↔ finitary monad correspondence (spec §25).
    MonadEquivalence,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum OperadValidation {
    /// Tree-substitution is associative (spec §26).
    Associativity,
    /// Identity operations act as units (spec §26).
    Unit,
    /// Symmetric group action is compatible (spec §26).
    Equivariance,
    /// Homotopy coherence at each level (spec §26).
    InfinityCoherence,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum FiniteCategoryValidation {
    ObjectReference,
    MorphismBoundary,
    IdentityTotality,
    IdentityLaw,
    CompositionTotality,
    CompositionClosure,
    CompositionBoundary,
    Associativity,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum RewritingValidation {
    /// All critical pairs join (local confluence).
    LocalConfluence,
    /// No infinite rewrite chains (termination).
    Termination,
    /// 2-cells resolve all non-confluent pairs (homotopy resolution).
    HomotopyResolution,
    /// Higher cells are coherent at declared truncation level.
    TruncationCoherence,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum ValidationUnit {
    FiniteCategory(FiniteCategoryValidation),
    Functor(FunctorValidation),
    NatTrans(NatTransValidation),
    Adjunction(AdjunctionValidation),
    Profunctor(ProfunctorValidation),
    HigherFunctor(HigherFunctorValidation),
    Coend(CoendValidation),
    KanExtension(KanExtensionValidation),
    Cauchy(CauchyValidation),
    Monad(MonadValidation),
    Condensation(CondensationValidation),
    Lawvere(LawvereValidation),
    Operad(OperadValidation),
    Rewriting(RewritingValidation),
    Other(String),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ValidationSeverity {
    Error,
    Warning,
    Info,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum ValidationLocation {
    Global,
    Object(String),
    Morphism(String),
    Named(String),
    Boundary {
        morphism: String,
        source: String,
        target: String,
    },
    Composition {
        first: String,
        second: String,
        composite: Option<String>,
    },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ValidationViolation {
    pub unit: ValidationUnit,
    pub location: ValidationLocation,
    pub message: String,
    pub severity: ValidationSeverity,
}

impl ValidationViolation {
    pub fn new(
        unit: ValidationUnit,
        location: ValidationLocation,
        message: impl Into<String>,
        severity: ValidationSeverity,
    ) -> Self {
        Self {
            unit,
            location,
            message: message.into(),
            severity,
        }
    }
}

// ---------------------------------------------------------------------------
// Validation report
// ---------------------------------------------------------------------------

/// A single validation result.
#[derive(Debug, Clone)]
pub struct ValidationResult {
    pub unit: String,
    pub passed: bool,
    pub violations: Vec<String>,
}

impl ValidationResult {
    pub fn pass(unit: &str) -> Self {
        Self {
            unit: unit.into(),
            passed: true,
            violations: Vec::new(),
        }
    }

    pub fn fail(unit: &str, violations: Vec<String>) -> Self {
        Self {
            unit: unit.into(),
            passed: false,
            violations,
        }
    }
}

/// A collection of validation results for a functor or related structure.
#[derive(Debug, Clone)]
pub struct ValidationReport {
    pub target_name: String,
    pub results: Vec<ValidationResult>,
    pub typed_violations: Vec<ValidationViolation>,
}

impl ValidationReport {
    pub fn new(name: &str) -> Self {
        Self {
            target_name: name.into(),
            results: Vec::new(),
            typed_violations: Vec::new(),
        }
    }

    pub fn add(&mut self, result: ValidationResult) {
        self.results.push(result);
    }

    pub fn add_violation(&mut self, violation: ValidationViolation) {
        self.results.push(ValidationResult::fail(
            &format!("{:?}", violation.unit),
            vec![violation.message.clone()],
        ));
        self.typed_violations.push(violation);
    }

    pub fn add_typed(&mut self, unit: &str, violations: Vec<ValidationViolation>) {
        if violations.is_empty() {
            self.results.push(ValidationResult::pass(unit));
        } else {
            let messages = violations
                .iter()
                .map(|violation| violation.message.clone())
                .collect();
            self.results.push(ValidationResult::fail(unit, messages));
            self.typed_violations.extend(violations);
        }
    }

    pub fn all_passed(&self) -> bool {
        self.results.iter().all(|r| r.passed) && self.typed_violations.is_empty()
    }

    pub fn failure_count(&self) -> usize {
        self.results.iter().filter(|r| !r.passed).count()
    }

    pub fn violation_count(&self) -> usize {
        self.typed_violations.len()
    }
}

//! Exact Reader/State/Writer arrow combinators. AuthorityEffect: None.
//! Callback termination and panic behavior remain the caller's trust boundary.
//! Errors discard returned state/logs; callback side effects are not rolled back.
//! Fan-out sends `Clone::clone` to the left callback and the original to the right.

use std::sync::Arc;

// ----------------------------------------------------------------------------
// Core Types
// ----------------------------------------------------------------------------

// Ctx: Configuration / Global Constants (Reader)
#[derive(Clone, Debug)]
pub struct Ctx {
    pub common_constants: Vec<num_rational::BigRational>,
    pub threshold: num_rational::BigRational,
}

// St: State (Accumulated suggestions, local symbol table)
#[derive(Clone, Debug, Default)]
pub struct St {
    pub suggestions: Vec<String>,
}

// Writer: Accumulated Violations
#[derive(Clone, Debug)]
pub struct Violation {
    pub rule_id: String,
    pub msg: String,
    pub severity: String,
}

pub type Writer = Vec<Violation>;
pub type ArrowResult<B> = Result<(Writer, St, B), anyhow::Error>;

pub type Arrow<A, B> = Arc<dyn Fn(&Ctx, St, A) -> ArrowResult<B> + Send + Sync>;

pub enum Either<L, R> {
    Left(L),
    Right(R),
}

// ----------------------------------------------------------------------------
// Combinators
// ----------------------------------------------------------------------------

pub fn arr<A, B, F>(f: F) -> Arrow<A, B>
where
    A: 'static + Send + Sync,
    B: 'static + Send + Sync,
    F: Fn(A) -> B + Send + Sync + 'static,
{
    Arc::new(move |_ctx, st, a| Ok((vec![], st, f(a))))
}

pub fn compose<A, B, C>(k1: Arrow<A, B>, k2: Arrow<B, C>) -> Arrow<A, C>
where
    A: 'static + Send + Sync,
    B: 'static + Send + Sync,
    C: 'static + Send + Sync,
{
    Arc::new(move |ctx, st, a| {
        let (mut w1, st1, b) = k1(ctx, st, a)?;
        let (w2, st2, c) = k2(ctx, st1, b)?;
        w1.extend(w2);
        Ok((w1, st2, c))
    })
}

pub fn tell<A>(v: Violation) -> Arrow<A, A>
where
    A: 'static + Clone + Send + Sync,
{
    Arc::new(move |_ctx, st, a| Ok((vec![v.clone()], st, a)))
}

// Lift a pure input transformation, as in arr; preserve state and emit no log.
pub fn map_input<A, B, F>(f: F) -> Arrow<A, B>
where
    A: 'static + Send + Sync,
    B: 'static + Send + Sync,
    F: Fn(A) -> B + Send + Sync + 'static,
{
    Arc::new(move |_ctx, st, a| Ok((vec![], st, f(a))))
}

// Fan-out: apply two arrows to the same input, combine their outputs
pub fn fanout<A, B, C>(ab: Arrow<A, B>, ac: Arrow<A, C>) -> Arrow<A, (B, C)>
where
    A: Clone + 'static + Send + Sync,
    B: 'static + Send + Sync,
    C: 'static + Send + Sync,
{
    Arc::new(move |ctx, st, a| {
        let (mut w1, st1, b) = ab(ctx, st, a.clone())?;
        let (w2, st2, c) = ac(ctx, st1, a)?;
        w1.extend(w2);
        Ok((w1, st2, (b, c)))
    })
}

// Split: apply two arrows to a pair, produce a pair
pub fn split<A, B, C, D>(f1: Arrow<A, B>, f2: Arrow<C, D>) -> Arrow<(A, C), (B, D)>
where
    A: 'static + Send + Sync,
    B: 'static + Send + Sync,
    C: 'static + Send + Sync,
    D: 'static + Send + Sync,
{
    Arc::new(move |ctx, st, (a, c)| {
        let (mut w1, st, b) = f1(ctx, st, a)?;
        let (w2, st, d) = f2(ctx, st, c)?;
        w1.extend(w2);
        Ok((w1, st, (b, d)))
    })
}

// Choice: apply either the left or right arrow depending on an Either value
pub fn choice<A, B, C>(f: Arrow<A, C>, g: Arrow<B, C>) -> Arrow<Either<A, B>, C>
where
    A: 'static + Send + Sync,
    B: 'static + Send + Sync,
    C: 'static + Send + Sync,
{
    Arc::new(move |ctx, st, input| match input {
        Either::Left(a) => f(ctx, st, a),
        Either::Right(b) => g(ctx, st, b),
    })
}
